/// <summary>
/// N.Freidenberger 08.07.2025
/// </summary>
public void itemCycleCountStart()
{
    AVAItemCycleCountOverviewLine       locItemCycleCountOverviewLine;
    firstSelectedLine.clear();
    for (locItemCycleCountOverviewLine = AVAItemCycleCountOverviewLine_ds.getFirst(true) ? AVAItemCycleCountOverviewLine_ds.getFirst(true) : AVAItemCycleCountOverviewLine_ds.cursor(); locItemCycleCountOverviewLine;locItemCycleCountOverviewLine = AVAItemCycleCountOverviewLine_ds.getNext())
    {
        if (!firstSelectedLine)
        {
            firstSelectedLine.data(locItemCycleCountOverviewLine);
        }
        AVAItemCycleCountStart  avaItemCycleCountStart = AVAItemCycleCountStart::newFromItemCycleCountOverviewLine(locItemCycleCountOverviewLine);
        avaItemCycleCountStart.start();
    }

}

/// <summary>
/// N.Freidenberger 27.05.2025
/// </summary>
/// <param name = "packedClass">packedClass</param>
/// <returns>unpack</returns>
public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            str invLocationPacked;
            [version, invLocationPacked] = packedClass;


            InvLocationFilter.text(invLocationPacked);

            return true;
        default :
            break;
    }

    return false;
}

