/// <summary>
/// N.Freidenberger 30.06.2025
/// </summary>
public void calcPackageQty()
{
    UnitOfMeasureConversion         unitOfMeasureConversion;
    UnitOfMeasure                   UnitOfMeasure;

    InventTable                     InventTable = InventTable::find(AVAItemCycleCountOverviewLine.ItemId);
    UnitOfMeasureSymbol             itemInventUnit = InventTable.inventUnitId();

    select firstonly unitOfMeasureConversion
        order by   NDXUnitLevel DESC
        where unitOfMeasureConversion.Product == InventTable.Product
        join unitOfMeasure
            where unitOfMeasure.RecId  == unitOfMeasureConversion.ToUnitOfMeasure
        && unitOfMeasure.Symbol == itemInventUnit;

    NDXUnitMinQty =  unitOfMeasureConversion.NDXUnitMinQty;

}

/// <summary>
/// N.Freidenberger
/// </summary>
/// <returns>boolean</returns>
public boolean checkSelectedLines()
{
    AVAItemCycleCountOverviewLine       locItemCycleCountOverviewLine;

    for (locItemCycleCountOverviewLine = AVAItemCycleCountOverviewLine_ds.getFirst(true) ? AVAItemCycleCountOverviewLine_ds.getFirst(true) : AVAItemCycleCountOverviewLine_ds.cursor(); locItemCycleCountOverviewLine;locItemCycleCountOverviewLine = AVAItemCycleCountOverviewLine_ds.getNext())
    {
        if(locItemCycleCountOverviewLine.NotCountable)
        {
            error("@NDX:NXANotCyclableLinesNotSelect");
            return false;     
        }

        if (locItemCycleCountOverviewLine.ItemCycleCountStarted)
        {
            Error("@NDX:NXAItemCycleCountIsAlreadyStarted");
            return false;
        }
    }

    return true;
}

