public void executeQuery()
{
    AVAItemCycleCountOverviewTable_ds.query().dataSourceTable(tableNum(AVAItemCycleCountOverviewTable)).clearRange(fieldnum(AVAItemCycleCountOverviewTable,InventLocationId));
    invLocationRange = SysQuery::findOrCreateRange(this.query().dataSourceTable(tableNum(AVAItemCycleCountOverviewTable)),fieldNum(AVAItemCycleCountOverviewTable,InventLocationId)) ;
    invLocationRange.value(InvLocationFilter.valueStr());
    super();
}

