    this.query().dataSourceTable(tableNum(AVAItemCycleCountOverviewLine)).addSortField(fieldNum(AVAItemCycleCountOverviewLine,NotCountable),SortOrder::Ascending);
    this.query().dataSourceTable(tableNum(AVAItemCycleCountOverviewLine)).addSortField(fieldNum(AVAItemCycleCountOverviewLine,RefPercent),SortOrder::Ascending);
