public void init()
{
    super();
    element.inventDimSetupObject().initQueryInventSum(inventSum_DS);
    inventSumItemRange = this.query().dataSourceTable(tableNum(InventSum)).addRange(fieldNum(InventSum,ItemId));
}

/// <summary>
/// N.Freidenberger 30.06.2025
/// </summary>
public void executeQuery()
{
    InventSum_ds.query().dataSourceTable(tableNum(InventSum)).clearRange(fieldnum(InventSum,ItemId));
    InventSum_ds.query().dataSourceTable(tableNum(InventSum)).addRange(fieldNum(InventSum,ItemId)).value(AVAItemCycleCountOverviewLine.ItemId);

    element.inventDimSetupObject().modifyQuery(inventSum_DS, inventDim_DS);
    /*if (inventSum_DS.query())
    {
        element.inventDimSetupObject().modifyQueryBasedOnDatasourceName(
                inventSum_DS.query(),
                inventSum_DS.name(),
                inventDim_DS);
    }    */

    inventAvailabilityFormCache.refreshCache();

    Query            query = InventSum_ds.query();
    QueryBuildDataSource  qbsDim = query.dataSourceName(inventDim_DS.name());
    qbsDim.clearRange(fieldNum(InventDim,InventLocationId));
    qbsDim.addRange(fieldNum(InventDim,InventLocationId)).value(AVAItemCycleCountOverviewTable.InventLocationId);
   // InventDim_ds.queryRun().query().dataSourceTable(tableNum(InventDim)).addRange(fieldNum(InventDim,InventLocationId)).value(InvLocationFilter.valueStr());

    super();
}

