/// <summary>
///  N.Freidenberger 11-07-2025
/// </summary>
public void jumpRef()
{
    if (AVAItemCycleCountOverviewObject.ItemCycleCountObject == AVAItemCycleCountObject::WorkTable)
    {
        WHSWorkTable        whsWorktable = whsWorktable::find(AVAItemCycleCountOverviewObject.ObjectId);

        Args    args = new Args();
        args.record(whsWorktable);
        args.caller(element);

        MenuFunction menuFunction = new MenuFunction(menuItemDisplayStr(WhsWorkTable), MenuItemType::Display);
        menuFunction.run(args);


    }
    if (AVAItemCycleCountOverviewObject.ItemCycleCountObject == AVAItemCycleCountObject::InventJournal)
    {
        InventJournalTable      inventJournalTable = InventJournalTable::find(AVAItemCycleCountOverviewObject.ObjectId);

        Args    args = new Args();
        args.record(inventJournalTable);
        args.caller(element);

        MenuFunction menuFunction = new MenuFunction(menuItemDisplayStr(InventJournalTableCount), MenuItemType::Display);
        menuFunction.run(args);

    }
    //super();
}

/// <summary>
/// N.Freidenberger 08.07.2025
