public void clicked()
{
    super();

    if (element.checkSelectedLines())
    {
        element.itemCycleCountStart();      

        AVAItemCycleCountOverviewLine_ds.executeQuery();
        if (firstSelectedLine)
        {
            AVAItemCycleCountOverviewLine_ds.positionToRecord(firstSelectedLine);
        }
    }          

}

