/// <summary>
///  N.Freidenberger 28/05/2025
/// </summary>
public void lookup()
{
    //super();
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation),this);
    Query           query  = new Query();
    query.addDataSource(tableNum(InventLocation)).addRange(fieldNum(InventLocation,AVACountCycleActive)).value(SysQuery::value(NoYes::Yes));

    sysTableLookup.addLookupfield(fieldNum(InventLocation,InventLocationId),true);
    sysTableLookup.addLookupfield(fieldNum(InventLocation,Name));
    sysTableLookup.addLookupfield(fieldNum(InventLocation,InventSiteId));
    sysTableLookup.addLookupfield(fieldNum(InventLocation,InventLocationType));
    sysTableLookup.addLookupfield(fieldNum(InventLocation,AVACountCycleActive));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

